<template>
  <div class="tag-management">
    <h2>卫星地面融合网络社区-标签管理</h2>

    <!-- 操作按钮 -->
    <el-card class="action-card">
      <el-button type="primary" icon="el-icon-plus" @click="addTag">添加标签</el-button>
    </el-card>

    <!-- 标签列表 -->
    <el-card>
      <el-table :data="tags" style="width: 100%" v-loading="loading">
        <el-table-column prop="id" label="ID" width="60"></el-table-column>
        <el-table-column prop="tagname" label="标签名称" width="200">
          <template slot-scope="scope">
            <el-tag size="medium">{{ scope.row.tagname }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column label="图标" width="100">
          <template slot-scope="scope">
            <img v-if="scope.row.avatar" :src="scope.row.avatar" class="tag-avatar" />
            <span v-else class="no-avatar">无</span>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="150" fixed="right">
          <template slot-scope="scope">
            <el-button type="text" size="small" @click="editTag(scope.row)">编辑</el-button>
            <el-button type="text" size="small" class="danger-text" @click="deleteTag(scope.row)">删除</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <!-- 添加/编辑标签对话框 -->
    <el-dialog :title="dialogTitle" :visible.sync="dialogVisible" width="500px">
      <el-form :model="tagForm" label-width="100px">
        <el-form-item label="标签名称">
          <el-input v-model="tagForm.tagname" placeholder="请输入标签名称"></el-input>
        </el-form-item>
        <el-form-item label="图标">
          <div class="avatar-upload">
            <el-radio-group v-model="avatarType" class="radio-group">
              <el-radio label="url">URL地址</el-radio>
              <el-radio label="upload">上传图片</el-radio>
            </el-radio-group>
            <el-input v-if="avatarType === 'url'" v-model="tagForm.avatar" placeholder="请输入图标URL"></el-input>
            <el-upload v-else
              class="avatar-uploader"
              action="/api/upload"
              :show-file-list="false"
              :on-success="handleAvatarSuccess"
              :before-upload="beforeAvatarUpload">
              <img v-if="tagForm.avatar" :src="tagForm.avatar" class="avatar">
              <i v-else class="el-icon-plus avatar-uploader-icon"></i>
            </el-upload>
          </div>
        </el-form-item>
      </el-form>
      <span slot="footer">
        <el-button @click="dialogVisible = false">取消</el-button>
        <el-button type="primary" @click="confirmSave">保存</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import { getTags, saveTag, deleteTag as deleteTagApi } from '@/api/tag'

export default {
  name: 'TagManagement',
  data() {
    return {
      tags: [],
      loading: false,
      dialogVisible: false,
      dialogTitle: '添加标签',
      tagForm: {
        id: null,
        tagname: '',
        avatar: ''
      },
      avatarType: 'url'
    }
  },
  created() {
    this.loadTags()
  },
  methods: {
    async loadTags() {
      this.loading = true
      try {
        const res = await getTags()
        this.tags = res.data || []
      } catch (error) {
        this.$message.error('加载标签列表失败')
      } finally {
        this.loading = false
      }
    },
    addTag() {
      this.dialogTitle = '添加标签'
      this.avatarType = 'url'
      this.tagForm = {
        id: null,
        tagname: '',
        avatar: ''
      }
      this.dialogVisible = true
    },
    editTag(tag) {
      this.dialogTitle = '编辑标签'
      this.avatarType = tag.avatar && tag.avatar.startsWith('http') ? 'url' : 'upload'
      this.tagForm = {
        id: tag.id,
        tagname: tag.tagname,
        avatar: tag.avatar
      }
      this.dialogVisible = true
    },
    handleAvatarSuccess(response, file) {
      if (response.code === 0) {
        this.tagForm.avatar = response.data.url
      } else {
        this.$message.error('图片上传失败')
      }
    },
    beforeAvatarUpload(file) {
      const isImage = file.type.startsWith('image/')
      const isLt2M = file.size / 1024 / 1024 < 2

      if (!isImage) {
        this.$message.error('请上传图片格式文件')
        return false
      }
      if (!isLt2M) {
        this.$message.error('图片大小不能超过 2MB')
        return false
      }
      return true
    },
    async confirmSave() {
      if (!this.tagForm.tagname) {
        this.$message.warning('请输入标签名称')
        return
      }

      try {
        await saveTag(this.tagForm)
        this.$message.success('保存成功')
        this.dialogVisible = false
        this.loadTags()
      } catch (error) {
        this.$message.error('保存失败')
      }
    },
    async deleteTag(tag) {
      try {
        await this.$confirm(`确定要删除标签「${tag.tagname}」吗？`, '警告', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        })

        await deleteTagApi(tag.id)
        this.$message.success('删除成功')
        this.loadTags()
      } catch (error) {
        if (error !== 'cancel') {
          this.$message.error('删除失败')
        }
      }
    }
  }
}
</script>

<style scoped>
.tag-management {
  padding: 20px;
}

.tag-management h2 {
  margin-bottom: 20px;
  font-size: 24px;
  color: #303133;
}

.action-card {
  margin-bottom: 20px;
}

.tag-avatar {
  width: 40px;
  height: 40px;
  object-fit: cover;
  border-radius: 4px;
}

.no-avatar {
  color: #909399;
}

.danger-text {
  color: #F56C6C;
}

.danger-text:hover {
  color: #f66;
}

.avatar-upload {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.radio-group {
  margin-bottom: 10px;
}

.avatar-uploader {
  border: 1px dashed #d9d9d9;
  border-radius: 6px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.avatar-uploader:hover {
  border-color: #409EFF;
}

.avatar-uploader-icon {
  font-size: 28px;
  color: #8c939d;
  width: 178px;
  height: 178px;
  line-height: 178px;
  text-align: center;
}

.avatar {
  width: 178px;
  height: 178px;
  display: block;
}
</style>



